package com.codeguardian.entity; import jakarta.persistence.*; import lombok.*; import java.time.LocalDateTime; @Entity @Table(name="knowledge_files") @Data @Builder @NoArgsConstructor @AllArgsConstructor public class KnowledgeFile{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)Long id;@Column(nullable=false)String filename;String contentType;Long size;@Column(nullable=false)String storagePath;LocalDateTime createdAt;@PrePersist void create(){if(createdAt==null)createdAt=LocalDateTime.now();}}
